Definition VSCR := EVNN.VSCR.

Theorem visit_double_nested_ok : forall (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  g_es g = c0 :: r0 ->
  PML.cps_heap L HI PC_VISIT_DOUBLE r sp VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r VSCR /\ PML.a0 R V /\ True /\ enc_inv M V S2 g /\ ev_guard (g_es g) EvDbl /\ PML.img_ro M /\ PML.lits_ok M /\
                ecredit L cr g kx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PML.a0 R' 1 /\ enc_inv M' V S2 g' /\ g_es g' = estep (g_es g) EvDbl /\ pay_ok EvDbl pay /\ g_len g' = g_len g + ev_ind (g_es g) EvDbl + pay /\
